const c = $input.first().json;
for (const key of ['wait_workflow_id', 'bug_fixes_table_id']) {
  if (typeof c[key] !== 'string' || !c[key] || c[key].startsWith('REPLACE_')) throw new Error('Configure ' + key);
}
if (c.type !== 'bug' || typeof c.confidence !== 'number' || !Number.isFinite(c.confidence)
    || c.confidence < 0.8 || c.confidence > 1 || !Number.isInteger(c.issue_number) || c.issue_number < 1) {
  throw new Error('A valid, confident bug Issue is required. Set the manual issue number above zero.');
}
if (!/^[A-Za-z0-9_.-]+$/.test(c.owner) || !/^[A-Za-z0-9_.-]+$/.test(c.repository)
    || !/^[A-Za-z0-9_./-]+$/.test(c.base_branch)) throw new Error('Invalid repository config');
const allowed_paths = JSON.parse(c.allowed_paths_json);
const required_ci_names = JSON.parse(c.required_ci_names_json);
if (!Array.isArray(allowed_paths) || !allowed_paths.length || allowed_paths.some(p => typeof p !== 'string' || !p.endsWith('/') || p.includes('..') || p.startsWith('/'))
    || !Array.isArray(required_ci_names) || required_ci_names.some(n => typeof n !== 'string')) throw new Error('Invalid path/CI allowlist');
const run_id = String($execution.id);
if (!/^[A-Za-z0-9_-]+$/.test(run_id)) throw new Error('Invalid execution ID');
return [{json: {...c, repo: c.owner + '/' + c.repository, run_id, n8n_execution: run_id,
 issue_key: `${c.owner}/${c.repository}#${c.issue_number}`, branch: `ai/fix-${c.issue_number}-${run_id}`,
 allowed_paths, required_ci_names}}];

const ctx = $('Fix Context').first().json;
const matches = $input.all().map(i => i.json).filter(r => r.issue_key === ctx.issue_key);
if (matches.length > 1) throw new Error('Duplicate bug_fixes rows');
return [{json: {...ctx, already_started: matches.length > 0, existing: matches[0] ?? null}}];

const ctx = $('Fix Context').first().json;
const issue = $input.first().json;
if (issue.number !== ctx.issue_number || issue.pull_request || issue.state !== 'open'
    || !issue.labels?.some(l => l.name === 'bug') || typeof issue.title !== 'string' || !issue.title.trim()
    || !String(issue.body ?? '').trim()) throw new Error('Issue must be open, have a bug label and a nonempty report');
return [{json: {...ctx, title: issue.title, body: issue.body, issue_url: issue.html_url}}];

const sha = $input.first().json.object?.sha;
if (!/^[0-9a-f]{40}$/.test(sha ?? '')) throw new Error('Invalid base SHA');
return [{json: {...$('Validate Bug Report').first().json, base_sha: sha}}];

const result = $input.first().json;
if (!Number.isSafeInteger(result.workflow_run_id) || result.workflow_run_id < 1) throw new Error('Dispatch response lacks workflow_run_id. Check API version 2026-03-10.');
return [{json: {...$('Run Context').first().json, fix_run_id: String(result.workflow_run_id)}}];

const input = $input.first().json;
const ctx = $('Fix Context').first().json;
return [{json: {issue_key:ctx.issue_key, status:"failed", error:'AI fix finished with ' + String(input.conclusion), updated_at:new Date().toISOString()}}];

const ctx = $('Fix Dispatch Context').first().json;
const sha = $input.first().json.object?.sha;
if (!/^[0-9a-f]{40}$/.test(sha ?? '') || sha === ctx.base_sha) throw new Error('Missing fix commit');
return [{json: {...ctx, head_sha:sha}}];

const c = $('Candidate').first().json;
const pr = $input.first().json;
if (!Number.isInteger(pr.number) || pr.head?.sha !== c.head_sha || pr.base?.ref !== c.base_branch) throw new Error('Unexpected created PR');
return [{json: {...c, pr_number:pr.number, pr_url:pr.html_url}}];

const run = $input.first().json.workflow_run_id;
if (!Number.isSafeInteger(run) || run < 1) throw new Error('Validation dispatch has no workflow_run_id');
return [{json: {...$('PR Context').first().json, validate_run_id: String(run)}}];

const input = $input.first().json;
const ctx = $('Fix Context').first().json;
return [{json: {issue_key:ctx.issue_key, status:"failed", error:'Candidate validation finished with ' + String(input.conclusion), updated_at:new Date().toISOString()}}];

const c = $('PR Context').first().json;
const pr = $('Read PR For Review').first().json;
const files = $input.all().map(i => i.json);
if (pr.state !== 'open' || pr.head?.sha !== c.head_sha || pr.base?.ref !== c.base_branch
    || !files.length || files.length >= 100 || files.length !== pr.changed_files) throw new Error('PR changed or diff is incomplete');
if (files.some(f => typeof f.patch !== 'string' || !c.allowed_paths.some(p => f.filename.startsWith(p))
    || !['modified','added'].includes(f.status))) throw new Error('Disallowed path, binary patch, deletion or rename');
const diff = files.map(f => ({file:f.filename,status:f.status,patch:f.patch}));
if (JSON.stringify(diff).length > c.max_diff_chars) throw new Error('Diff too large for automatic review');
return [{json: {issue:{title:c.title,body:c.body}, head_sha:c.head_sha, diff,
 tests:{conclusion:$('Validate Result').first().json.conclusion,url:$('Validate Result').first().json.actions_url}}}];

const out = $input.first().json;
const raw = out.output ?? out.text ?? out;
const r = typeof raw === 'string' ? JSON.parse(raw) : raw;
const c = $('PR Context').first().json;
if (!r || r.reviewed_sha !== c.head_sha || !['approve','request_changes'].includes(r.verdict)
    || !Array.isArray(r.findings) || typeof r.summary !== 'string' || !r.summary.trim()) throw new Error('Invalid review result');
if (r.findings.some(f => !['low','medium','high','critical'].includes(f.severity)
    || typeof f.file !== 'string' || typeof f.reason !== 'string')) throw new Error('Invalid findings');
const approved = r.verdict === 'approve' && !r.findings.some(f => ['high','critical'].includes(f.severity));
return [{json:{...r, issue_key:c.issue_key, approved, gate_started_ms:Date.now(),
 review_json:JSON.stringify(r), comment:`AI review ${r.reviewed_sha}\nVerdict: ${r.verdict}\n\n${r.summary}\n\n`
   + r.findings.map(f=>`${f.severity}: ${f.file}: ${f.reason}`).join('\n')}}];

const c = $('PR Context').first().json;
const pr = $('Fresh PR').first().json;
const review = $('Review Decision').first().json;
const validation = $('Validate Result').first().json;
const checks = $('Candidate Check Runs').first().json;
const statuses = $('Candidate Statuses').first().json;
let blocked = '';
let pending = false;
if (!review.approved || review.reviewed_sha !== c.head_sha || validation.expected_sha !== c.head_sha
    || !validation.completed || validation.conclusion !== 'success') blocked = 'Review/validation mismatch';
if (pr.state !== 'open' || pr.draft || pr.head?.sha !== c.head_sha || pr.head?.ref !== c.branch
    || pr.head?.repo?.full_name !== c.repo || pr.base?.repo?.full_name !== c.repo
    || pr.base?.ref !== c.base_branch) blocked = 'PR or head changed';
if ($('Fresh Base').first().json.object?.sha !== c.base_sha) blocked = 'Base branch advanced: restart with fresh base';
if (!Array.isArray(checks.check_runs) || checks.total_count > checks.check_runs.length
    || !Array.isArray(statuses.statuses) || statuses.total_count > statuses.statuses.length) blocked = 'Incomplete CI response';
if (!blocked) {
  const names = new Set();
  for (const check of checks.check_runs) {
    names.add(check.name);
    if (check.head_sha !== c.head_sha) {blocked = 'CI SHA mismatch'; break;}
    if (check.status !== 'completed') pending = true;
    else if (check.conclusion !== 'success') blocked = 'Check did not succeed: ' + check.name;
  }
  for (const status of statuses.statuses) {
    names.add(status.context);
    if (status.state === 'pending') pending = true;
    else if (status.state !== 'success') blocked = 'Status did not succeed: ' + status.context;
  }
  if (c.required_ci_names.some(name => !names.has(name))) pending = true;
  if (pr.mergeable === null) pending = true;
  else if (pr.mergeable !== true) blocked = 'PR is not mergeable';
}
if (!blocked && pending && Date.now() - review.gate_started_ms > c.readiness_timeout_seconds * 1000) blocked = 'Timed out waiting for CI/mergeability';
return [{json:{issue_key:c.issue_key, pr_number:c.pr_number, pr_url:c.pr_url, head_sha:c.head_sha,
 ready:!blocked && !pending, wait_more:!blocked && pending, reason:blocked,
 enable_merge:c.enable_merge === true, status:blocked ? 'blocked' : pending ? 'waiting_ci' : 'ready_for_merge'}}];

const input = $input.first().json;
const ctx = $('Fix Context').first().json;
return [{json: {issue_key:ctx.issue_key, status:"blocked", error:input.reason, updated_at:new Date().toISOString()}}];

const r = $input.first().json;
if (r.merged !== true || !/^[0-9a-f]{40}$/.test(r.sha ?? '')) throw new Error('GitHub did not confirm merge');
return [{json:{issue_key:$('Fix Context').first().json.issue_key,status:'merged',error:'',updated_at:new Date().toISOString()}}];
